(()=>{const home=document.getElementById('homeView'),hero=document.getElementById('heroFrame');function update(){const isHome=window.ctuavDemo?.route==='home';const r=hero.getBoundingClientRect();document.documentElement.toggleAttribute('data-home-hero-visible',isHome&&r.bottom>0)}addEventListener('scroll',update,{passive:true});home.addEventListener('scroll',update,{passive:true});addEventListener('resize',update);addEventListener('hashchange',()=>requestAnimationFrame(update));new ResizeObserver(update).observe(hero);update()})();